// 数据验证节点 - 基础数据验证
// 在数据清洗之前进行验证，过滤明显无效的数据

const items = $input.all();

// ============================================
// 验证规则配置
// ============================================

const validationRules = {
  // 标题长度限制
  titleMinLength: 5,
  titleMaxLength: 200,

  // 内容长度限制
  contentMinLength: 10,
  contentMaxLength: 50000,

  // 数值范围限制
  maxLikes: 100000000,      // 最大点赞数（防止异常数据）
  maxComments: 10000000,    // 最大评论数
  maxViews: 10000000000,    // 最大播放量

  // 时间戳范围（毫秒）
  minTimestamp: 946684800000,   // 2000-01-01
  maxTimestamp: Date.now() + 86400000, // 允许未来1天（时区差异）

  // 必填字段
  requiredFields: ['title', 'content_id']
};

// ============================================
// 验证函数
// ============================================

function validateItem(item) {
  const errors = [];
  const warnings = [];
  const data = item.json || item;

  // 1. 必填字段检查
  if (!data.title || data.title.trim() === '') {
    errors.push('标题(title)不能为空');
  }

  if (!data.content_id && !data.aweme_id && !data.note_id && !data.video_id) {
    errors.push('内容ID不能为空');
  }

  // 2. 标题长度验证
  if (data.title) {
    const titleLength = data.title.trim().length;
    if (titleLength < validationRules.titleMinLength) {
      errors.push(`标题过短（${titleLength}字符，最少${validationRules.titleMinLength}字符）`);
    }
    if (titleLength > validationRules.titleMaxLength) {
      warnings.push(`标题过长（${titleLength}字符，建议不超过${validationRules.titleMaxLength}字符）`);
    }
  }

  // 3. 内容长度验证
  const content = data.content || data.desc || '';
  const contentLength = content.trim().length;
  if (contentLength < validationRules.contentMinLength) {
    errors.push(`内容过短（${contentLength}字符，最少${validationRules.contentMinLength}字符）`);
  }
  if (contentLength > validationRules.contentMaxLength) {
    warnings.push(`内容过长（${contentLength}字符，建议不超过${validationRules.contentMaxLength}字符）`);
  }

  // 4. 数值范围验证
  const likes = parseInt(data.liked_count || data.like_count || 0);
  if (likes < 0) {
    errors.push('点赞数不能为负数');
  }
  if (likes > validationRules.maxLikes) {
    warnings.push(`点赞数异常大（${likes}），可能是异常数据`);
  }

  const comments = parseInt(data.comment_count || 0);
  if (comments < 0) {
    errors.push('评论数不能为负数');
  }
  if (comments > validationRules.maxComments) {
    warnings.push(`评论数异常大（${comments}），可能是异常数据`);
  }

  // 5. 时间戳验证
  if (data.create_time) {
    const createTime = parseInt(data.create_time);
    if (isNaN(createTime)) {
      errors.push('创建时间格式无效');
    } else {
      // 判断是秒还是毫秒
      const timestamp = createTime < 10000000000 ? createTime * 1000 : createTime;
      if (timestamp < validationRules.minTimestamp) {
        errors.push('创建时间过旧（早于2000年）');
      }
      if (timestamp > validationRules.maxTimestamp) {
        warnings.push('创建时间在未来，可能是时区问题或异常数据');
      }
    }
  }

  if (data.add_ts) {
    const addTime = parseInt(data.add_ts);
    if (isNaN(addTime)) {
      errors.push('入库时间格式无效');
    } else {
      const timestamp = addTime < 10000000000 ? addTime * 1000 : addTime;
      if (timestamp < validationRules.minTimestamp) {
        errors.push('入库时间过旧');
      }
      if (timestamp > validationRules.maxTimestamp) {
        warnings.push('入库时间在未来');
      }
    }
  }

  // 6. 异常数据检测
  // 点赞数为0但评论数很多（可能是异常）
  if (likes === 0 && comments > 100) {
    warnings.push('点赞数为0但评论数较多，可能是异常数据');
  }

  // 7. 平台标识验证
  const platform = data.platform || '';
  const validPlatforms = ['douyin', 'xhs', 'bilibili', 'kuaishou', 'tieba', 'weibo', 'zhihu'];
  if (platform && !validPlatforms.includes(platform)) {
    warnings.push(`未知的平台标识: ${platform}`);
  }

  // 8. 重复数据检测（基于内容ID）
  // 注意：这个需要在全局范围内检测，这里只做标记

  return {
    valid: errors.length === 0,
    errors: errors,
    warnings: warnings,
    data: data
  };
}

// ============================================
// 批量验证
// ============================================

const validatedItems = items.map(item => {
  const result = validateItem(item);

  return {
    json: {
      ...result.data,
      _validation: {
        valid: result.valid,
        errors: result.errors,
        warnings: result.warnings,
        error_count: result.errors.length,
        warning_count: result.warnings.length
      }
    }
  };
});

// 统计信息
const stats = {
  total: validatedItems.length,
  valid: validatedItems.filter(item => item.json._validation.valid).length,
  invalid: validatedItems.filter(item => !item.json._validation.valid).length,
  with_warnings: validatedItems.filter(item => item.json._validation.warnings.length > 0).length
};

// 返回验证结果
return validatedItems;

// 注意：如果需要过滤无效数据，可以在下一个节点中使用IF节点
// 条件：{{ $json._validation.valid }} === true

// 数据清洗节点 - 处理数字格式转换和时间戳统一
// 输入：从数据库查询的原始数据
// 输出：清洗后的标准化数据

const items = $input.all();

// ============================================
// 工具函数：数字格式转换
// ============================================

/**
 * 将字符串格式的数字转换为数值
 * 支持格式：
 * - "1234" -> 1234
 * - "9.2万" -> 92000
 * - "1.5千" -> 1500
 * - "10.5万" -> 105000
 */
function parseNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 0;
  }

  // 如果已经是数字类型，直接返回
  if (typeof value === 'number') {
    return value;
  }

  // 转换为字符串处理
  const str = String(value).trim();

  // 处理"万"、"千"等中文单位
  if (str.includes('万')) {
    const num = parseFloat(str.replace('万', ''));
    return isNaN(num) ? 0 : Math.round(num * 10000);
  }

  if (str.includes('千')) {
    const num = parseFloat(str.replace('千', ''));
    return isNaN(num) ? 0 : Math.round(num * 1000);
  }

  // 处理普通数字字符串
  const num = parseFloat(str);
  return isNaN(num) ? 0 : Math.round(num);
}

/**
 * 安全地解析数字，如果失败返回默认值
 */
function safeParseNumber(value, defaultValue = 0) {
  try {
    return parseNumber(value);
  } catch (e) {
    return defaultValue;
  }
}

// ============================================
// 工具函数：时间戳统一处理
// ============================================

/**
 * 统一时间戳处理
 * 输入可能是秒或毫秒，统一转换为毫秒
 */
function normalizeTimestamp(timestamp, platform) {
  if (!timestamp) {
    return null;
  }

  // 判断单位：小于10位数是秒，大于等于10位数是毫秒
  const ts = Number(timestamp);
  if (isNaN(ts)) {
    return null;
  }

  // 根据平台判断（更准确）
  const platformTimeUnits = {
    douyin: 'seconds',      // create_time是秒
    xhs: 'milliseconds',    // time是毫秒
    bilibili: 'seconds',    // create_time是秒
    kuaishou: 'seconds',    // create_time是秒
    weibo: 'seconds',       // create_time是秒
    tieba: 'string',        // publish_time是字符串
    zhihu: 'string'         // created_time是字符串
  };

  const unit = platformTimeUnits[platform] || 'auto';

  if (unit === 'milliseconds') {
    return ts; // 已经是毫秒
  } else if (unit === 'seconds') {
    return ts * 1000; // 转换为毫秒
  } else if (unit === 'string') {
    // 字符串格式的时间，尝试解析
    return parseStringTime(timestamp);
  } else {
    // 自动判断
    if (ts < 10000000000) {
      return ts * 1000; // 秒转毫秒
    } else {
      return ts; // 已经是毫秒
    }
  }
}

/**
 * 解析字符串格式的时间
 */
function parseStringTime(timeStr) {
  if (!timeStr) return null;

  try {
    // 尝试解析常见格式
    const date = new Date(timeStr);
    if (!isNaN(date.getTime())) {
      return date.getTime();
    }

    // 尝试解析Unix时间戳字符串
    const ts = parseInt(timeStr);
    if (!isNaN(ts)) {
      return ts < 10000000000 ? ts * 1000 : ts;
    }

    return null;
  } catch (e) {
    return null;
  }
}

/**
 * 将时间戳转换为可读日期格式
 */
function formatTimestamp(timestamp) {
  if (!timestamp) return null;

  try {
    const date = new Date(timestamp);
    return date.toISOString().replace('T', ' ').substring(0, 19);
  } catch (e) {
    return null;
  }
}

// ============================================
// 数据清洗主函数
// ============================================

function cleanAndNormalizeData(item) {
  const platform = item.platform || item.json?.platform || 'douyin';

  // 提取原始数据
  const raw = item.json || item;

  // 1. 数字字段转换
  const likes = safeParseNumber(raw.liked_count || raw.like_count || raw.likes || 0);
  const comments = safeParseNumber(raw.comment_count || raw.comments || raw.comment_count_from_table || 0);
  const shares = safeParseNumber(raw.share_count || raw.shares || 0);
  const collected = safeParseNumber(raw.collected_count || raw.collected || 0);

  // 处理播放量（不同平台字段名不同）
  let views = 0;
  if (raw.video_play_count) views = safeParseNumber(raw.video_play_count);
  else if (raw.viewd_count) views = safeParseNumber(raw.viewd_count);
  else if (raw.views) views = safeParseNumber(raw.views);

  // 2. 时间戳统一处理
  let createTime = null;
  let createTimeReadable = null;

  // 优先使用create_time，如果没有则使用time
  if (raw.create_time) {
    createTime = normalizeTimestamp(raw.create_time, platform);
    createTimeReadable = formatTimestamp(createTime);
  } else if (raw.time) {
    createTime = normalizeTimestamp(raw.time, platform);
    createTimeReadable = formatTimestamp(createTime);
  }

  // 处理入库时间
  let addTime = null;
  let addTimeReadable = null;
  if (raw.add_ts) {
    addTime = normalizeTimestamp(raw.add_ts, platform);
    addTimeReadable = formatTimestamp(addTime);
  }

  // 3. 内容处理
  const title = (raw.title || '').trim();
  const content = (raw.content || raw.desc || '').trim();
  const contentLength = content.length;
  const titleLength = title.length;

  // 4. 关键词处理
  const sourceKeyword = raw.source_keyword || '';
  const extractedKeywords = sourceKeyword ? [sourceKeyword] : [];

  // 5. 计算衍生指标
  // 互动率计算
  let interactionRate = 0;
  if (views > 0) {
    interactionRate = (likes + comments) / views;
  } else if (likes > 0 || comments > 0) {
    // 无播放量时，使用点赞评论比
    interactionRate = comments / (likes + comments || 1);
  }

  // 热度评分基础值
  const heatScoreBase = likes + comments * 2 + shares * 0.5 + collected * 0.3;

  // 时间衰减因子（新内容加权）
  let timeDecay = 1;
  if (createTime) {
    const now = Date.now();
    const daysSince = (now - createTime) / (1000 * 60 * 60 * 24);
    timeDecay = Math.max(0.5, 1 - daysSince / 30); // 30天内线性衰减
  }

  const heatScore = heatScoreBase * timeDecay;

  // 6. 数据验证标记
  const isValid = 
    title.length >= 5 && 
    title.length <= 200 && 
    content.length >= 10 &&
    likes >= 0 && 
    comments >= 0 &&
    createTime !== null;

  // 7. 构建标准化数据
  const cleaned = {
    // 原始ID
    id: raw.id,
    content_id: raw.content_id || raw.aweme_id || raw.note_id || raw.video_id,
    platform: platform,

    // 用户信息
    user_id: raw.user_id || '',
    nickname: raw.nickname || '',
    avatar: raw.avatar || '',
    ip_location: raw.ip_location || '',

    // 内容信息
    title: title,
    content: content,
    content_length: contentLength,
    title_length: titleLength,
    content_url: raw.content_url || raw.aweme_url || raw.note_url || raw.video_url || '',

    // 关键词
    source_keyword: sourceKeyword,
    extracted_keywords: extractedKeywords,

    // 标准化数字字段
    likes: likes,
    comments: comments,
    shares: shares,
    collected: collected,
    views: views,
    sub_comments: safeParseNumber(raw.sub_comment_count || 0),

    // 时间戳（统一为毫秒）
    create_time: createTime,
    create_time_readable: createTimeReadable,
    add_ts: addTime,
    add_ts_readable: addTimeReadable,

    // 衍生指标
    interaction_rate: parseFloat(interactionRate.toFixed(4)),
    heat_score: parseFloat(heatScore.toFixed(2)),
    time_decay_factor: parseFloat(timeDecay.toFixed(4)),

    // 元数据
    content_type: raw.content_type || raw.aweme_type || raw.type || '',
    is_valid: isValid,
    quality_score: isValid ? 0.85 : 0.5, // 基础质量评分，后续可优化

    // 保留原始数据（用于调试）
    _raw: {
      liked_count: raw.liked_count,
      comment_count: raw.comment_count,
      share_count: raw.share_count,
      create_time: raw.create_time,
      add_ts: raw.add_ts
    }
  };

  return cleaned;
}

// ============================================
// 批量处理
// ============================================

const cleanedItems = items.map(item => {
  try {
    return cleanAndNormalizeData(item);
  } catch (error) {
    // 错误处理：记录错误但继续处理其他数据
    console.error('数据清洗错误:', error);
    return {
      ...item.json,
      is_valid: false,
      error: error.message
    };
  }
});

// 返回清洗后的数据
return cleanedItems.map(item => ({ json: item }));

// TODO: 请实现Top10计算逻辑
// 功能: 计算各类别的Top10热门内容
// Mode: Run Once for All Items
// 参考: 工作流设计文档.md 中的热度评分计算逻辑

const groupedData = $('数据分组').item.json;

// 计算热度评分函数
function calculateHeatScore(item) {
  const likes = item.likes || 0;
  const comments = item.comments || 0;
  const shares = item.shares || 0;
  const collected = item.collected || 0;

  let baseScore = likes * 1.0 + comments * 2.0 + shares * 0.5 + collected * 0.3;

  // 时间衰减因子
  if (item.create_time) {
    const now = Date.now();
    const daysSince = (now - item.create_time) / (1000 * 60 * 60 * 24);
    const timeDecay = Math.max(0.5, 1 - daysSince / 30);
    baseScore = baseScore * timeDecay;
  }

  return baseScore;
}

// 为每个分类计算Top10
const top10ByCategory = {};
Object.keys(groupedData.groupedByCategory).forEach(category => {
  const items = groupedData.groupedByCategory[category];
  items.forEach(item => {
    item.heat_score = calculateHeatScore(item);
  });

  top10ByCategory[category] = items
    .sort((a, b) => b.heat_score - a.heat_score)
    .slice(0, 10);
});

return {
  json: {
    top10ByCategory,
    generatedAt: new Date().toISOString()
  }
};

// TODO: 请实现统计分析逻辑
// 功能: 生成全量数据统计
// Mode: Run Once for All Items

const allItems = $('过滤低置信度').all().map(item => item.json);
const top10Data = $('计算Top10').item.json;

// 生成统计信息
const stats = {
  total_count: allItems.length,
  category_stats: {},
  platform_stats: {},
  generated_at: new Date().toISOString()
};

// 按分类统计
allItems.forEach(item => {
  const category = item.category || '未分类';
  if (!stats.category_stats[category]) {
    stats.category_stats[category] = {
      count: 0,
      total_likes: 0,
      total_comments: 0
    };
  }
  stats.category_stats[category].count++;
  stats.category_stats[category].total_likes += item.likes || 0;
  stats.category_stats[category].total_comments += item.comments || 0;
});

// 计算平均值
Object.keys(stats.category_stats).forEach(category => {
  const cat = stats.category_stats[category];
  cat.avg_likes = cat.total_likes / cat.count;
  cat.avg_comments = cat.total_comments / cat.count;
});

return {
  json: {
    ...stats,
    top10: top10Data.top10ByCategory
  }
};

