// 合并AI响应节点
// 功能：将AI返回的结果合并到批量数据中（每个批次输出1条）
// Mode: ✅ Run Once for Each Item
//
// 说明：
// - 在 “Run Once for Each Item” 模式下，只能用 $input.item 取当前这一条
// - HTTP Request 节点会为每个输入批次返回一个输出，并通过 pairedItem 关联到原始批次
// - 我们用 pairedItem.item 作为批次索引，到“准备批量分类”里把对应的 batch 拿回来

// 当前 HTTP Request（AI批量分类）输出的这一条
const currentItem = $input.item;
const aiResponse = currentItem.json;

// pairedItem.item 指向“AI批量分类”的输入索引，也就是“准备批量分类”的批次索引
const pairedIndex =
  typeof currentItem.pairedItem?.item === 'number'
    ? currentItem.pairedItem.item
    : 0;

// ✅ 注意：这里必须用 .all() 拿到“准备批量分类”的所有批次数据，否则 prompt/items 会丢
const preparedBatches = $('准备批量分类').all();

// 找到这一批对应的原始 batch 数据
const batchData = preparedBatches[pairedIndex]?.json ?? {
  batchIndex: pairedIndex + 1,
  batchSize: 0,
  totalBatches: preparedBatches.length,
  prompt: '',
  items: [],
};

// 输出：每个批次 1 条，带上 prompt / items / aiResponse
return {
  json: {
    ...batchData,
    aiResponse,
  },
};

// 解析批量分类结果节点
// 功能：解析AI返回的批量分类结果，合并到原始数据中
// Mode: ✅ Run Once for All Items
//
// 上游输入结构（来自「合并AI响应」节点，每个 item 表示一个批次）：
// {
//   batchIndex: number,      // 批次序号（1-based）
//   batchSize: number,       // 本批条数
//   totalBatches: number,    // 总批次数
//   prompt: string,          // 发送给 AI 的完整 prompt
//   items: [ {...}, ... ],   // 本批原始内容数组（每条是一个 json）
//   aiResponse: {...}        // AI 返回的原始响应（DeepSeek / OpenAI 风格）
// }
//
// 本节点目标：把所有批次展开，变成一条条带分类结果的 item 流输出。

// 一次性拿到上游「合并AI响应」输出的所有批次
const batchResults = $input.all();

// ============================================
// 工具函数：解析 AI 返回的 JSON
// ============================================

function parseAIResponse(aiResponse) {
  if (!aiResponse) {
    return null;
  }

  // 提取 AI 返回内容
  let content = '';
  if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
    // OpenAI / DeepSeek Chat Completion 格式
    content = aiResponse.choices[0].message.content;
  } else if (aiResponse.content) {
    // 兼容 content 字段
    content = aiResponse.content;
  } else if (typeof aiResponse === 'string') {
    content = aiResponse;
  }

  if (!content) {
    return null;
  }

  // 清理可能的 markdown 代码块包裹并解析 JSON
  try {
    content = content.trim();
    if (content.startsWith('```json')) {
      content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '');
    } else if (content.startsWith('```')) {
      content = content.replace(/```\s*/g, '');
    }

    const parsed = JSON.parse(content);

    // 确保返回数组
    if (Array.isArray(parsed)) {
      return parsed;
    } else if (parsed.results && Array.isArray(parsed.results)) {
      return parsed.results;
    } else {
      return [parsed];
    }
  } catch (e) {
    console.error('解析AI响应失败:', e);
    console.error('响应内容(前500字符):', content.substring(0, 500));
    return null;
  }
}

// ============================================
// 主逻辑：把分类结果合并回原始 items
// ============================================

const allClassifiedItems = [];

batchResults.forEach(batchResult => {
  const batchData = batchResult.json || {};
  const items = Array.isArray(batchData.items) ? batchData.items : [];
  const aiResponse = batchData.aiResponse;

  // 解析本批 AI 的分类结果
  const classifications = parseAIResponse(aiResponse);

  if (!classifications || !Array.isArray(classifications)) {
    console.warn(`批次 ${batchData.batchIndex} 解析失败，使用默认“未分类”结果`);

    // 解析失败时，为每条 item 填一个兜底分类
    items.forEach(item => {
      allClassifiedItems.push({
        ...item,
        category: '未分类',
        categories: [],
        category_confidence: 0,
        category_reason: 'AI解析失败',
        keywords: [],
        tags: [],
        intent: '',
        content_type: '',
        classification_error: true,
      });
    });
    return;
  }

  // 将分类结果逐条合并到原始 items
  items.forEach((item, index) => {
    let classification = null;

    // 1）优先按同索引匹配
    if (classifications[index]) {
      classification = classifications[index];
    } else {
      // 2）尝试按 ID 匹配
      classification = classifications.find(c =>
        c.id === item.id ||
        c.id === item.content_id ||
        (c.id === undefined && index < classifications.length)
      );
    }

    // 3）仍然匹配不到则给一个默认分类
    if (!classification) {
      classification = {
        categories: [],
        primary_category: '未分类',
        confidence: 0,
        reason: '未找到匹配的分类结果',
        keywords: [],
        tags: [],
        intent: '',
        content_type: '',
      };
    }

    allClassifiedItems.push({
      ...item,
      category: classification.primary_category || '未分类',
      categories: classification.categories || [],
      category_confidence: classification.confidence || 0,
      category_reason: classification.reason || '',
      keywords: classification.keywords || [],
      tags: classification.tags || [],
      intent: classification.intent || '',
      content_type: classification.content_type || '',
    });
  });
});

// ============================================
// 返回结果（含兜底逻辑）
// ============================================

// 如果一个结果都没有，返回一条 warning，避免 n8n 显示 “No output data returned”
if (allClassifiedItems.length === 0) {
  return [
    {
      json: {
        _warning:
          '解析批量分类结果：没有生成任何输出项（通常是上游合并后的 batchData.items 为空或 AI 返回为空）',
        batches_in: batchResults.length,
        sample_batch: batchResults[0]?.json
          ? {
              batchIndex: batchResults[0].json.batchIndex,
              batchSize: batchResults[0].json.batchSize,
              totalBatches: batchResults[0].json.totalBatches,
              items_len: Array.isArray(batchResults[0].json.items)
                ? batchResults[0].json.items.length
                : null,
              has_aiResponse: !!batchResults[0].json.aiResponse,
            }
          : null,
      },
    },
  ];
}

// 正常情况：展开为逐条 item 流
return allClassifiedItems.map(item => ({ json: item }));

// TODO: 请实现数据分组逻辑
