  // 按平台分组
  if (!groupedByPlatform[platform]) {
    groupedByPlatform[platform] = [];
  }
  groupedByPlatform[platform].push(data);

  // 按分类+平台组合分组
  const key = `${category}_${platform}`;
  if (!groupedByCategoryAndPlatform[key]) {
    groupedByCategoryAndPlatform[key] = [];
  }
  groupedByCategoryAndPlatform[key].push(data);
});

return {
  json: {
    groupedByCategory,
    groupedByPlatform,
    groupedByCategoryAndPlatform,
