console.log('⚠️ 请确保这些文件夹已存在，否则文件保存可能失败');
console.log('💡 建议：手动创建 outputs/report 文件夹');

// ============================================
// 返回原始数据
// ============================================

// 不做任何修改，直接返回输入数据
return $input.all();

// 解析工作流参数，生成标准化配置
// 输入：来自“工作流参数” Set 节点

const input = $input.item.json || {};

const keywordsRaw = String(input.keywords_raw || '')
  .split(/[,\n，]/)
  .map(k => k.trim())
  .filter(k => k.length > 0);

const days = Number(input.days ?? 7);
const limit = Number(input.limit ?? 1000);
const useSourceKeyword = input.useSourceKeyword !== false;

// 输出为后续“数据查询-SQL生成”节点使用
return {
  json: {
    keywords: keywordsRaw.length > 0 ? keywordsRaw : ['论文', 'AI', '人工智能'],
    days,
    limit,
    useSourceKeyword,
    platforms: ['douyin']  // Fada抖音：只分析抖音
  }
