// 数据查询节点 - Fada抖音专用 SQL 生成
// 功能：根据“工作流参数”节点中的关键词和时间范围，动态生成只针对 douyin_aweme 的 SQL
// Mode: Run Once for All Items

const params = $('解析关键词参数').item.json || {};

// ============================================
// 配置
// ============================================

const config = {
  keywords: params.keywords || ['论文', 'AI', '人工智能'],
  days: params.days ?? 7,
  limit: params.limit ?? 1000,
  useSourceKeyword: params.useSourceKeyword !== false
};

// ============================================
// 工具函数：生成关键词条件
// ============================================

function generateKeywordCondition(keywords, useSourceKeyword = true) {
  if (!keywords || keywords.length === 0) {
    return '1=1'; // 无关键词限制
  }

  const escapedKeywords = keywords
    .map(k => `'${String(k).replace(/'/g, "''")}'`)
    .join(', ');

  if (useSourceKeyword) {
    const keywordCondition = `da.source_keyword IN (${escapedKeywords})`;
    const fallbackCondition = keywords
      .map(k => {
        const escaped = String(k).replace(/'/g, "''");
        return `(da.title LIKE '%${escaped}%' OR da.desc LIKE '%${escaped}%')`;
      })
      .join(' OR ');

    return `(
      ${keywordCondition}
      OR (da.source_keyword IS NULL AND (${fallbackCondition}))
    )`;
  } else {
    const conditions = keywords
      .map(k => {
        const escaped = String(k).replace(/'/g, "''");
        return `(da.title LIKE '%${escaped}%' OR da.desc LIKE '%${escaped}%')`;
      })
      .join(' OR ');
    return `(${conditions})`;
  }
}

// 时间范围（最近 N 天），针对 add_ts（毫秒）
function generateTimeCondition(days) {
  return `da.add_ts >= UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL ${days} DAY)) * 1000`;
}

// ============================================
// 生成抖音 SQL
// ============================================

function generateDouyinSQL(config) {
  const keywordCondition = generateKeywordCondition(
    config.keywords,
    config.useSourceKeyword
  );
  const timeCondition = generateTimeCondition(config.days);

  const sql = `
SELECT 
  'douyin' AS platform,
  da.id,
  da.aweme_id AS content_id,
  da.user_id,
  da.nickname,
  da.avatar,
  da.title,
  da.desc AS content,
  da.source_keyword,
  da.liked_count,
  da.comment_count,
  da.share_count,
  da.collected_count,
  da.create_time,
  da.add_ts,
  da.last_modify_ts,
  da.aweme_type AS content_type,
  da.ip_location,
  da.aweme_url AS content_url,
  -- 评论数（备用）
  (SELECT COUNT(*) 
   FROM douyin_aweme_comment dac 
   WHERE dac.aweme_id = da.aweme_id) AS comment_count_from_table,
  -- 子评论数（备用）
  (SELECT COALESCE(SUM(CAST(dac.sub_comment_count AS UNSIGNED)), 0) 
   FROM douyin_aweme_comment dac 
   WHERE dac.aweme_id = da.aweme_id) AS sub_comment_count
FROM douyin_aweme da
WHERE
  ${keywordCondition}
  AND ${timeCondition}
  AND da.title IS NOT NULL
  AND da.title != ''
  AND da.desc IS NOT NULL
ORDER BY da.add_ts DESC
LIMIT ${config.limit};
  `.trim();

  return sql;
}

const sql = generateDouyinSQL(config);

// 输出给下游 MySQL 节点使用
return {
  json: {
    sql,
    config
  }
};

// 生成内容生成上下文 - 为阶段4内容生成提供 summary / top10_list / key_findings
// Mode: Run Once for All Items

const stats = $('统计分析').item.json;
const top10ByCategory = stats.top10 || {};

// 1. 总体摘要
