  const sortedCats = Object.entries(stats.category_stats)
    .sort((a, b) => (b[1].count || 0) - (a[1].count || 0))
    .slice(0, 3);

  if (sortedCats.length > 0) {
    const catSummary = sortedCats
      .map(([name, s]) => `${name}（${s.count} 条，平均点赞约 ${Math.round(s.avg_likes || 0)}）`)
      .join('，');
    summaryLines.push(`其中，数量和互动表现较突出的类别包括：${catSummary}。`);
  }
}

const summary = summaryLines.join('\n');

// 2. Top10 列表（按分类）
const top10Lines = [];
Object.keys(top10ByCategory).forEach(category => {
  const list = top10ByCategory[category] || [];
  if (!list.length) return;

  top10Lines.push(`### 类别：${category}`);
  list.slice(0, 10).forEach((item, idx) => {
    const title = (item.title || '').trim();
    const likes = item.likes || 0;
    const comments = item.comments || 0;
    const heat = item.heat_score || 0;
    const url = item.content_url || '';
    top10Lines.push(
      `- TOP${idx + 1}：${title}（点赞：${likes}，评论：${comments}，热度评分：${heat.toFixed(2)}）` +
      (url ? ` [链接](${url})` : '')
    );
  });
  top10Lines.push(''); // 空行分隔
});

const top10_list = top10Lines.join('\n');

// 3. 关键发现（简单规则版，可以后面再优化）
const keyFindingLines = [];

if (stats.category_stats) {
  const sortedByCount = Object.entries(stats.category_stats)
    .sort((a, b) => (b[1].count || 0) - (a[1].count || 0));
  if (sortedByCount.length > 0) {
    const [topCat, topStat] = sortedByCount[0];
    keyFindingLines.push(
      `- 在所有抖音内容中，「${topCat}」类占比最高，共 ${topStat.count} 条，是当前最值得重点关注的方向。`
    );
  }
}

if (stats.platform_stats && stats.platform_stats.douyin) {
  const ps = stats.platform_stats.douyin;
  keyFindingLines.push(
    `- 从平台维度看，本次分析仅针对抖音，平均点赞约 ${Math.round(ps.avg_likes || 0)}，平均评论约 ${Math.round(ps.avg_comments || 0)}。`
  );
}

if (!keyFindingLines.length) {
  keyFindingLines.push('- 当前样本量有限，建议后续扩大抓取范围以便形成更稳定的趋势判断。');
}

const key_findings = keyFindingLines.join('\n');

// 4. 输出给阶段4使用
return {
  json: {
    summary,
    top10_list,
    key_findings,
    platform: '抖音',
    platform_key: 'douyin',
    style: '适合抖音的短视频口语化文案风格，轻松、有画面感，带一点故事性和互动感。',
    word_limit: '800-1200字'
  }
};

