// 格式化内容
// 功能: 格式化生成的内容，提取标题、正文、标签
// Mode: Run Once for Each Item

const aiResponse = $input.item.json;

// 提取AI生成的内容
let content = '';
if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  content = aiResponse.choices[0].message.content;
} else if (aiResponse.content) {
  content = aiResponse.content;
}

const lines = String(content || '').split('\n');
let title = '';
let body = '';
let tags = [];

// 提取标题（第一个 # 开头的行）
for (const line of lines) {
  if (line.startsWith('# ')) {
    title = line.replace('# ', '').trim();
    break;
  }
}

// 提取正文（去除标题后的所有内容）
let titleFound = false;
for (const line of lines) {
  if (line.startsWith('# ')) {
    titleFound = true;
    continue;
  }
  if (titleFound) {
    body += line + '\n';
  }
}

// 提取标签（从内容中查找 #标签）
const tagRegex = /#([^\s#]+)/g;
const matches = String(content || '').match(tagRegex);
if (matches) {
  tags = matches.map(tag => tag.replace('#', ''));
}

// 平台从上游继承（若无则默认为 douyin）
const platform = $json.platform_key || $json.platform || 'douyin';

return {
  json: {
    title: title || '未命名文章',
    content: body.trim() || content,
    raw_content: content,
    tags,
    generated_at: new Date().toISOString(),
    platform
  }
};

// 发布准备 - 修复保存内容节点（支持二进制输出）
// 功能: 准备发布所需的数据和文件，将 raw_content 转换为二进制格式供 Write Binary File 节点使用
// Mode: Run Once for Each Item

const contentData = $('格式化内容').item.json;

// 准备发布数据
const publishData = {
  platform: contentData.platform || 'douyin',
  title: contentData.title,
  content: contentData.content,
  raw_content: contentData.raw_content,
  tags: contentData.tags || [],
  publish_time: new Date().toISOString(),
  metadata: {
    generated_at: contentData.generated_at,
    word_count: (contentData.content || '').length,
    tag_count: (contentData.tags || []).length,
    source: 'Fada抖音'
  }
};

// ============================================
// 关键修复：将 raw_content 字符串转换为二进制格式
// ============================================

const rawContentText = String(publishData.raw_content || '');
const rawContentBuffer = Buffer.from(rawContentText, 'utf8');
const rawContentBase64 = rawContentBuffer.toString('base64');

// 返回 JSON 和 Binary 数据
return {
  json: {
    ...publishData,
    publish_data: publishData  // 方便"保存元数据"节点使用
  },
  binary: {
    raw_content: {
      data: rawContentBase64,
      mimeType: 'text/markdown',
      fileName: `${publishData.platform}_${publishData.publish_time.replace(/[:.]/g, '-')}.md`
    }
  }
};

// 转换元数据为二进制
// Mode: Run Once for Each Item

const input = $input.item.json || {};
const publishData = input.publish_data || input;

const jsonString = JSON.stringify(publishData, null, 2);
const jsonBase64 = Buffer.from(jsonString, 'utf8').toString('base64');

return {
  json: input,
  binary: {
    publish_data: {
      data: jsonBase64,
      mimeType: 'application/json',
      fileName: `${publishData.platform || 'douyin'}_${(publishData.publish_time || new Date().toISOString()).replace(/[:.]/g, '-')}.json`
    }
  }
};

